// ============================================================================
// NORMALIZADOR OMNICANAL ROBUSTO CON FALLBACK — BuyaCAR Tunja
// ============================================================================
const item = $input.first().json;
const body = item.body || item;

let channel = 'facebook_marketplace';
let senderId = 'cliente-meta';
let message = '¿Sigue disponible?';
let adTitle = '';

// 1. Meta (Facebook Marketplace / Messenger)
if (body.entry?.[0]?.messaging) {
  const m = body.entry[0].messaging[0];
  channel = body.object === 'instagram' ? 'instagram' : 'facebook_marketplace';
  senderId = m.sender?.id || 'meta-user';
  message = m.message?.text || '¿Sigue disponible?';
  adTitle = m.message?.referral?.ad_title || m.referral?.ad_title || '';
}
// 2. WhatsApp
else if (body.data?.message || body.messages || body.entry?.[0]?.changes?.[0]?.value?.messages) {
  channel = 'whatsapp';
  const waMsg = body.data?.message || body.messages?.[0] || body.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
  senderId = body.data?.key?.remoteJid || waMsg?.from || body.phone || 'whatsapp-user';
  message = waMsg?.conversation || waMsg?.extendedTextMessage?.text || waMsg?.text?.body || '¿Sigue disponible?';
}
// 3. Fallback genérico
else {
  channel = body.channel_id || 'facebook_marketplace';
  senderId = body.customer_alias || body.sender_id || 'lead-facebook';
  message = body.message || body.text || '¿Sigue disponible?';
  adTitle = body.ad_title || '';
}

return [{
  json: {
    channel_id: channel,
    customer_alias: senderId,
    ad_title: adTitle,
    message: String(message).trim()
  }
}];

// ============================================================================
// RESPUESTA FORMATEADA Y RESISTENTE A FALLOS
// ============================================================================
const item = $input.first().json;
return [{
  json: {
    status: 'success',
    channel: item.channel_id,
    recipient_id: item.customer_alias,
    reply_to_customer: item.reply_text,
    backed_numbers_verified: item.backed_numbers_verified,
    ready_for_channel_dispatch: true
  }
}];

// ============================================================================
// REGISTRO DE ESCALAMIENTO (Regateo, Quejas, Retoma)
// ============================================================================
const item = $input.first().json;
return [{
  json: {
    status: 'escalated_to_human',
    reason: item.escalation_reason,
    customer_alias: item.customer_alias,
    ad_title: item.ad_title,
    action: 'asignar_vendedor_buyaCAR'
  }
}];
